"use strict";
// Callback-invoking API surface for the TYPED-callback boundary tests: the
// package calls scriptc closures with primitives, objects, undefined
// holes, and surplus arguments, awaits async callbacks, and catches what
// they throw. Signatures are any-heavy (like commander's .action) so the
// STATIC side's annotations decide each callback's shape.
exports.withNumbers = function withNumbers(fn) {
  return String(fn(2, 3.5));
};
exports.withString = function withString(fn) {
  return fn("abc");
};
exports.withBool = function withBool(fn) {
  return fn(true) ? "T" : "F";
};
exports.maybe = function maybe(fn, give) {
  return give ? fn("given") : fn();
};
exports.withOptions = function withOptions(fn) {
  return fn({ name: "opt", count: 2, extra: [1, 2, 3], ignored: "surplus key" });
};
exports.extraArgs = function extraArgs(fn) {
  return fn(1, 2, { tag: "x" }, "surplus", 99);
};
exports.catching = function catching(fn, arg) {
  try {
    return "ok:" + fn(arg);
  } catch (e) {
    return "caught:" + (e instanceof TypeError) + ":" + e.message;
  }
};
exports.chainLog = async function chainLog(fn) {
  const r = await fn("go");
  console.log("then:" + r);
};
exports.chainCatchLog = async function chainCatchLog(fn) {
  try {
    await fn();
    console.log("no-throw");
  } catch (e) {
    console.log("err:" + (e instanceof Error) + ":" + e.message);
  }
};
exports.fire = function fire(fn) {
  fn("later");
  return "fired";
};
exports.collectTwice = function collectTwice(fn) {
  const once = fn("first");
  const twice = fn("second", once);
  return JSON.stringify(twice);
};
